// DETERMINISTIC STEP: Validate incoming ticket has required fields.
// If anything is missing, we mark it invalid and route it to the fallback queue.

const body = $input.first().json.body || $input.first().json;

const name = (body.name || '').trim();
const email = (body.email || '').trim();
const message = (body.message || '').trim();

const emailOk = /^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(email);
const isValid = name.length > 0 && emailOk && message.length >= 5;

return [{
  json: {
    name,
    email,
    message,
    isValid,
    validationError: isValid ? '' : 'Missing or invalid name/email/message',
    receivedAt: new Date().toISOString()
  }
}];

// DETERMINISTIC STEP: Parse the AI's JSON safely and apply a confidence threshold.
// If the AI returned junk or low confidence, mark for manual review (fallback).

const aiText = $input.first().json.content?.[0]?.text
  || $input.first().json.text
  || $input.first().json.message?.content
  || '';

// Pull the original ticket fields forwarded alongside
const ticket = $('2. Validate Input').first().json;

let parsed = null;
try {
  const match = aiText.match(/\{[\s\S]*\}/);
  parsed = match ? JSON.parse(match[0]) : null;
} catch (e) {
  parsed = null;
}

const CONFIDENCE_THRESHOLD = 0.6;
const valid = parsed
  && ['billing','technical','account','general'].includes(parsed.category)
  && ['high','medium','low'].includes(parsed.urgency)
  && typeof parsed.confidence === 'number';

const needsManualReview = !valid || parsed.confidence < CONFIDENCE_THRESHOLD;

return [{
  json: {
    name: ticket.name,
    email: ticket.email,
    message: ticket.message,
    receivedAt: ticket.receivedAt,
    category: valid ? parsed.category : 'general',
    urgency: valid ? parsed.urgency : 'medium',
    sentiment: valid ? parsed.sentiment : 'neutral',
    summary: valid ? parsed.summary : 'Could not classify automatically',
    is_common_question: valid ? !!parsed.is_common_question : false,
    confidence: valid ? parsed.confidence : 0,
    needsManualReview,
    routedReason: needsManualReview ? 'Low confidence or invalid AI output' : 'Auto-triaged'
  }
}];

