// DETERMINISTIC STEP: Build the human-escalation alert payload for high-urgency tickets.
// In a real system this would notify an on-call agent and pause for approval (human-in-the-loop).
const t = $input.first().json;
return [{
  json: {
    ...t,
    action: 'ESCALATED_TO_HUMAN',
    draftReply: '',
    alert: `⚠️ HIGH URGENCY ticket from ${t.name} (${t.email}). Sentiment: ${t.sentiment}. Issue: ${t.summary}. A human must review before replying.`
  }
}];

// DETERMINISTIC STEP: attach the AI-drafted reply to the ticket record so it can be logged/sent.
const reply = $input.first().json.content?.[0]?.text || $input.first().json.text || '';
const t = $('5. Parse & Confidence Check').first().json;
return [{ json: { ...t, action: 'AUTO_REPLIED', draftReply: reply, alert: '' } }];

// DETERMINISTIC STEP: format the manual-review fallback record.
const t = $input.first().json;
return [{
  json: {
    name: t.name || 'unknown',
    email: t.email || 'unknown',
    message: t.message || '',
    category: t.category || 'general',
    urgency: t.urgency || 'medium',
    sentiment: t.sentiment || 'neutral',
    summary: t.summary || (t.validationError || 'Sent to manual review'),
    confidence: t.confidence || 0,
    action: 'MANUAL_REVIEW',
    draftReply: '',
    alert: 'Ticket needs human triage (invalid input or low AI confidence).',
    receivedAt: t.receivedAt || new Date().toISOString()
  }
}];

// FINAL OUTPUT (deterministic): build the triage record + the outgoing message.
// This stands in for 'Log to Google Sheet' + 'Send Email' — it produces the exact
// same structured record, shown directly inside n8n (no external credentials needed).
const t = $input.first().json;

const outgoingMessage = t.action === 'AUTO_REPLIED'
  ? t.draftReply
  : (t.action === 'ESCALATED_TO_HUMAN'
      ? '[NOT SENT] Held for human review — ' + (t.alert || '')
      : '[NOT SENT] Sent to manual review queue.');

return [{
  json: {
    '— TRIAGE RECORD —': '',
    receivedAt: t.receivedAt,
    name: t.name,
    email: t.email,
    category: t.category,
    urgency: t.urgency,
    sentiment: t.sentiment,
    summary: t.summary,
    confidence: t.confidence,
    action: t.action,
    '— OUTGOING MESSAGE —': '',
    emailSubject: 'Re: your support request [' + t.category + ']',
    emailTo: t.email,
    outgoingMessage
  }
}];
